seq = "".join(l.strip() for l in open("region.fasta") if not l.startswith(">")).upper()
n=len(seq)
def rc(s): return s.translate(str.maketrans("ACGT","TGCA"))[::-1]
stop={"TAA","TAG","TGA"}
def get_orfs(t, strand):
    out=[]
    for f in range(3):
        start=None
        for j in range(f,len(t)-2,3):
            cod=t[j:j+3]
            if cod=="ATG" and start is None: start=j
            if cod in stop:
                if start is not None:
                    aa=(j-start)//3
                    if aa>=50: out.append((start,j+3,aa))
                start=None
    return out
print("Plus-strand ORFs (>=50 aa), 1-based inclusive, coding start..(stop-1):")
for a,b,aa in get_orfs(seq,'+'):
    print("  %d - %d  (%d codons)"%(a+1,b,aa))
print("Reverse-strand ORFs (plus-strand coords):")
r=rc(seq)
for a,b,aa in get_orfs(r,'-'):
    print("  %d - %d  (%d codons)"%(n-b+1,n-a,aa))

# longest exact repeat location
L=12
seen={}
for i in range(n-L+1):
    sub=seq[i:i+L]
    if sub in seen:
        print("\nLongest exact repeat (%d bp):"%L, sub, "at", seen[sub]+1, "and", i+1)
    seen[sub]=i

# palindrome location
comp={'A':'T','T':'A','G':'C','C':'G'}
best=(0,0)
for c in range(n):
